-- europcar-wonderboom-airport-wonderboom (owner)
UPDATE businesses SET description = 'Europcar Wonderboom Airport is a car-rental branch of the Europcar South Africa network, serving travellers who need a vehicle after flying into Wonderboom Airport as well as local Pretoria residents and businesses. The branch offers hire for personal travel, holidays, airport transfers and local transport, alongside corporate and business-rental services for companies needing vehicles for staff, clients or business trips. Rentals can include extras such as child seats, GPS equipment and additional drivers, depending on availability. The branch is at Wonderboom Airport on Lintveldt Road, Annlin, Pretoria North, and is listed as a Deliver/Collect location, so delivery and collection can be arranged through the branch when booking. It is open Monday to Friday from 8am to 5pm and Saturday from 8am to 1pm, and closed on Sundays and public holidays. It suits travellers who want to collect a rental car directly at the airport rather than travelling into central Pretoria.', description_enriched_at = datetime('now') WHERE slug = 'europcar-wonderboom-airport-wonderboom' AND description = 'This Europcar branch serves travellers at Wonderboom National Airport in Annlin.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
